import{_ as r,a0 as n,w as d,s as p,ao as l,I as o,x as a,a1 as s,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"淺談主機名 | LCTT x X-CMD","titleTemplate":false,"description":"淺談主機名 | LCTT (202110) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"淺談主機名 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"淺談主機名 | LCTT (202110) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202110/20211011 What is a hostname","title":"淺談主機名","tag":"202110","desc":""},"relativePath":"202110/20211011 What is a hostname.md","filePath":"[post].md"}'),h={name:"202110/20211011 What is a hostname.md"};function c(u,e,b,m,g,k){const t=n("Link");return d(),p("div",null,[e[18]||(e[18]=l('<h1 id="淺談主機名" tabindex="-1">淺談主機名 <a class="header-anchor" href="#淺談主機名" aria-label="Permalink to “淺談主機名”">​</a></h1><blockquote><p>主機名是人類用來指代特定計算機的標籤。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202110/19/134329lwni9tlq9h3u4f4o.jpg" alt=""></p><p>計算機有網絡地址，但人類通常很難記住它們。主機名是幫助人類參考特定計算機的標籤。例如，你可能不會導航到 <code>192.168.1.4</code>，而是導航到 <code>linuxlaptop</code> 或 <code>linuxlaptop.local</code>。</p><h3 id="地址和名稱" tabindex="-1">地址和名稱 <a class="header-anchor" href="#地址和名稱" aria-label="Permalink to “地址和名稱”">​</a></h3><p>所有聯網的計算機（也被稱為<ruby>主機<rt>host</rt></ruby>）都需要一個地址：一個與之相關的唯一數字，以使數據報文能夠在它們之間進行正確的數據通信。這就是所謂的<ruby>互聯網協議<rt>Internet Protocol</rt></ruby>（IP）地址。數字 <code>54.204.39.132</code> 是一個<ruby>互聯網協議第四版<rt>Internet Protocol version 4</rt></ruby>（IPv4）地址。較新的 IPv6 地址要長得多，像這樣：<code>2001:0db6:3c4d:0017:0000:0000:2a2f:1a2b</code>。 哇！這將是很難記住的！</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ip addr show</span></span></code></pre></div><p>計算機也可以被賦予標籤。被稱為<ruby>主機名<rt>hostname</rt></ruby>，這些是友好的名稱，便於參考。我可以把我的計算機的主機名設置為 <code>copperhead</code>。只要這個名字在網絡上是唯一的，所有其他用户和計算機都可以把 <code>copperhead</code> 作為地址，而不是 IP 地址。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ hostname -s</span></span></code></pre></div><p>你可以更新你的計算機的主機名。</p>',10)),o("p",null,[e[1]||(e[1]=a("閲讀 Seth Kenlon 的文章 ",-1)),s(t,{href:"https://opensource.com/article/21/10/how-change-hostname-linux"},{default:i(()=>[...e[0]||(e[0]=[a("如何在 Linux 上更改主機名",-1)])]),_:1}),e[2]||(e[2]=a("，瞭解如何在 Linux 上這樣做。",-1))]),e[19]||(e[19]=l('<h4 id="完全限定域名" tabindex="-1">完全限定域名 <a class="header-anchor" href="#完全限定域名" aria-label="Permalink to “完全限定域名”">​</a></h4><p>從技術上講，主機名包括一個域名。如果我的域名是 <code>mycompany.com</code>，那麼我的計算機的主機名是 <code>copperhead.mycompany.com</code>，以句點分隔。這就形成了一個<ruby>完全限定域名<rt>fully qualified domain name</rt></ruby>（FQDN）。這很重要，因為 IP 地址可以解析為 FQDN。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>host.domain.topleveldomain</span></span></code></pre></div><p>例如：<code>www.example.com</code> 是一個完全限定域名。</p><p>你的域名一般已經確定了，所以你只負責提供主機部分。本文的重點是主機。</p><h4 id="名稱解析" tabindex="-1">名稱解析 <a class="header-anchor" href="#名稱解析" aria-label="Permalink to “名稱解析”">​</a></h4><p>將 IP 地址轉換為相應的主機名的過程被稱為名稱解析。這個過程首先發生在本地主機表中。Linux 使用文件 <code>/etc/hosts</code> 來存儲這個表。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cat /etc/hosts</span></span></code></pre></div><p>還有一個分層的、去中心化的基於網絡的系統提供解析，稱為<ruby>域名系統<rt>Domain Name System</rt></ruby>（DNS）。這時 FQDN 變得非常重要。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ dig www.opensource.com</span></span></code></pre></div><h3 id="名稱的樂趣" tabindex="-1">名稱的樂趣 <a class="header-anchor" href="#名稱的樂趣" aria-label="Permalink to “名稱的樂趣”">​</a></h3><p>為我們的計算機起名字可能很有趣。如果你有很多，你可以使用一個主題。我曾經為一家公司工作，該公司將所有的服務器都以蛇命名。</p><p>後來我工作的一家公司，我是一個數據中心經理，使用啤酒品牌。當我們收到一個新的服務器時，這很令人興奮，因為我會給開發團隊發郵件徵求建議。我們大約有 100 台服務器。這些提供了一個有趣的清單，反映了公司的多樣性。我們有從庫爾斯和百威到阿姆斯特爾和淺粉象的一切。我們有虎牌啤酒、勝獅啤酒和札幌啤酒等等！</p><p>我們認為這很酷！然後，想像一下，當你試圖記住盧雲堡是擁有最多內存的虛擬化服務器，佩羅尼是 SQL 資料庫服務器，喜力是新的域控制器時，會發生什麼，特別是對於一個快速發展的公司的新員工。</p><h3 id="慣例" tabindex="-1">慣例 <a class="header-anchor" href="#慣例" aria-label="Permalink to “慣例”">​</a></h3><p>當然，主機名是所有者的選擇，所以請盡情發揮。然而，根據環境的不同，使用容易記憶的名字或基於命名慣例的名字可能更有意義，因為這些名字有利於描述主機。</p><h4 id="有用的名字" tabindex="-1">有用的名字 <a class="header-anchor" href="#有用的名字" aria-label="Permalink to “有用的名字”">​</a></h4><p>如果你想放棄有趣的東西，並對你的系統進行有益的命名，也許可以考慮它們的功能。資料庫服務器可以被命名為 <code>database1</code>、<code>database2</code>、<code>database3</code> 等等。Web 服務器可以命名為 <code>webserver1</code>、<code>webserver2</code> 等等。</p><h4 id="位置名稱" tabindex="-1">位置名稱 <a class="header-anchor" href="#位置名稱" aria-label="Permalink to “位置名稱”">​</a></h4><p>我在許多客户那裏使用了一種技術，用一組字符的位置來命名服務器主機，這些字符描述了該系統的一個方面，有助於識別。例如，如果我正在為內政部（DOI）開發一個業務流程管理（BPM）系統，我就會在命名規則中加入他們的縮寫詞。</p><p>此外，就像許多大型企業、金融機構和政府一樣，他們可能有不同的數據中心，位於不同的地理位置，以達到性能或災難恢復的目的。因此，比如説，位於北美大陸東海岸的數據中心被稱為 ED（East Data center），而位於西海岸的數據中心則是 WD（West Data center）。</p><p>所有這些信息將彙集到一個名稱中，如 <code>doibpm1ed</code> 或 <code>doibpm1wd</code>。因此，雖然這些名字看起來不長，但在這個項目上工作的人可以很容易地識別它們的目的和位置，而且這個名字甚至可以對潛在的惡意者混淆它們的用途。換句話説，業主可以選擇只對內部人員有意義的命名方式</p><h3 id="互聯網標準" tabindex="-1">互聯網標準 <a class="header-anchor" href="#互聯網標準" aria-label="Permalink to “互聯網標準”">​</a></h3><p>有幾個標準管理着主機名。你可以在<ruby>互聯網工程任務組<rt>Internet Engineering Task Force</rt></ruby>（IETF）維護的<ruby>意見徵求<rt>Requests for Comment</rt></ruby>（RFC）中找到這些標準。由此，請遵守以下規定：</p><ul><li>主機名的長度應該在 1 到 63 個 ASCII 字符之間</li><li>一個 FQDN 的最大長度為 253 個 ASCII 字符</li><li>不區分大小寫</li><li>允許的字符：<code>a</code> 到 <code>z</code>，<code>0</code> 到 <code>9</code>，<code>-</code>（連字符），和 <code>_</code>（下劃線）。</li></ul><p>我希望這篇文章能幫助你澄清主機名。玩得開心，發揮創意。</p><hr>',27)),o("p",null,[e[4]||(e[4]=a("via: ",-1)),s(t,{href:"https://opensource.com/article/21/10/what-hostname"},{default:i(()=>[...e[3]||(e[3]=[a("https://opensource.com/article/21/10/what-hostname",-1)])]),_:1})]),o("p",null,[e[9]||(e[9]=a("作者：",-1)),s(t,{href:"https://opensource.com/users/alanfdoss"},{default:i(()=>[...e[5]||(e[5]=[a("Alan Formy-Duval",-1)])]),_:1}),e[10]||(e[10]=a(" 選題：",-1)),s(t,{href:"https://github.com/lujun9972"},{default:i(()=>[...e[6]||(e[6]=[a("lujun9972",-1)])]),_:1}),e[11]||(e[11]=a(" 譯者：",-1)),s(t,{href:"https://github.com/geekpi"},{default:i(()=>[...e[7]||(e[7]=[a("geekpi",-1)])]),_:1}),e[12]||(e[12]=a(" 校對：",-1)),s(t,{href:"https://github.com/wxy"},{default:i(()=>[...e[8]||(e[8]=[a("wxy",-1)])]),_:1})]),o("p",null,[e[15]||(e[15]=a("本文由 ",-1)),s(t,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...e[13]||(e[13]=[a("LCTT",-1)])]),_:1}),e[16]||(e[16]=a(" 原創編譯，",-1)),s(t,{href:"https://linux.cn/"},{default:i(()=>[...e[14]||(e[14]=[a("Linux中國",-1)])]),_:1}),e[17]||(e[17]=a(" 榮譽推出",-1))])])}const C=r(h,[["render",c]]);export{x as __pageData,C as default};
